import {config,samples,faqs,code} from './content.js';

export const escape = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m15.5 15.5 5 5"/>',
 arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',down:'<path d="M12 3v12m-5-5 5 5 5-5M5 16v5h14v-5"/>',
 play:'<path d="m9 5 11 7-11 7Z"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 4H4v16h16v-6"/>',
 image:'<rect x="3" y="3" width="18" height="18" rx="4"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',
 scan:'<path d="M8 3H4v4m12-4h4v4M4 17v4h4m8 0h4v-4M7 8h10M7 12h10M7 16h6"/>',
 document:'<path d="M14 3H5v18h14V8Zm0 0v5h5M8 12h8M8 16h6"/>',
 video:'<rect x="3" y="5" width="13" height="14" rx="3"/><path d="m16 10 5-3v10l-5-3"/>',
 audio:'<path d="M3 10v4m4-7v10m5-14v18m5-14v10m4-7v4"/>',
 code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>',
 shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6Z"/><path d="m8 12 3 3 5-6"/>',
 monitor:'<rect x="2" y="3" width="20" height="14" rx="3"/><path d="M8 21h8m-4-4v4"/>',
 check:'<path d="m5 12 5 5L20 7"/>',folder:'<path d="M3 7V4h7l3 3h8v13H3Z"/>',
 sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',
 moon:'<path d="M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10Z"/>',
 github:'<path d="M9 21v-3c-4 1-4-2-5-2m11 5v-4c0-1-.5-2-1-2 4-.5 6-2 6-6 0-1-.5-3-1.5-3.5.2-1-.1-2-.5-3-2 0-3 1-4 1.5a12 12 0 0 0-5 0C8 3 7 2 5 2c-.4 1-.7 2-.5 3C3.5 6 3 8 3 9c0 4 2 5.5 6 6-.5.5-1 1-1 2"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="3"/><path d="M16 8V3H3v13h5"/>',
 expand:'<path d="M15 3h6v6m0-6-7 7M9 21H3v-6m0 6 7-7"/>',
 refresh:'<path d="M20 12a8 8 0 1 1-2.6-5.9"/><path d="M20 4v5h-5"/>',wifi:'<path d="M3 8c6-5 12-5 18 0M6 12c4-3 8-3 12 0m-8 4c2-1 2-1 4 0M12 20h.01M3 3l18 18"/>',
 keyboard:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="M5 9h1m3 0h1m3 0h1m3 0h1M5 12h1m3 0h1m3 0h1m3 0h1M7 16h10"/>',
 gauge:'<path d="M4 18a9 9 0 1 1 16 0"/><path d="m12 14 4-5"/><circle cx="12" cy="14" r="1.2"/>',
 globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c3 3 3 15 0 18M12 3c-3 3-3 15 0 18"/>',
 cloud:'<path d="M7 19h10a4 4 0 0 0 .5-8 6 6 0 0 0-11.5 1.5A3.5 3.5 0 0 0 7 19Z"/>',
 trash:'<path d="M4 7h16M9 7V4h6v3m-9 0 1 14h10l1-14M10 11v6m4-6v6"/>',
};
// The Windows logo itself: four squares in Windows blue, not a line drawing.
const windowsLogo=cls=>`<svg class="icon windows-logo ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path fill="#0078D4" d="M2 2h9.5v9.5H2zM12.5 2H22v9.5h-9.5zM2 12.5h9.5V22H2zM12.5 12.5H22V22h-9.5z"/></svg>`;
export const icon=(name,cls='')=>name==='windows'?windowsLogo(cls):`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.document}</svg>`;
export const brand=(large=false)=>`<a class="brand ${large?'brand-large':''}" href="#" aria-label="Trovara home"><img src="assets/logo.png" alt="" width="36" height="36"><span>Trovara</span></a>`;
export const getButton=(cls='')=>`<a class="button button-primary ${cls}" href="#download">${icon('windows')}<span>Get Trovara for Windows</span>${icon('arrow','button-arrow')}</a>`;

export function Navigation(){return `<header class="site-header"><div class="container nav-inner">${brand()}<nav class="desktop-nav" aria-label="Main navigation"><a href="#how-it-works">How it works</a><a href="#file-types">File types</a><a href="#faq">FAQs</a><a href="${config.repository}" target="_blank" rel="noopener noreferrer">GitHub ${icon('external')}</a></nav><div class="nav-actions"><div class="theme-control"><button class="icon-button" id="theme-toggle" aria-label="Change theme" aria-haspopup="true" aria-expanded="false" aria-controls="theme-menu">${icon('sun','theme-light-icon')}${icon('moon','theme-dark-icon')}</button><div class="theme-menu" id="theme-menu" hidden><span class="menu-label">APPEARANCE</span><div role="group" aria-label="Appearance">${[['system','monitor','System'],['light','sun','Light'],['dark','moon','Dark']].map(([mode,glyph,label])=>`<button type="button" data-theme-choice="${mode}" aria-pressed="false">${icon(glyph)}<span>${label}</span>${icon('check','theme-check')}</button>`).join('')}</div></div></div><a class="button button-small button-primary nav-download" href="#download">Get Trovara ${icon('down')}</a><button class="icon-button mobile-menu-toggle" id="mobile-menu-toggle" aria-label="Open navigation" aria-controls="mobile-nav" aria-expanded="false">${icon('menu')}</button></div></div><nav class="mobile-nav container" id="mobile-nav" aria-label="Mobile navigation" hidden><a href="#how-it-works">How it works</a><a href="#file-types">File types</a><a href="#faq">FAQs</a><a href="${config.repository}">GitHub</a><a href="#download">Get Trovara for Windows</a></nav></header>`;}

export function sampleMedia(sample,{large=false}={}){
 if(sample.id==='code')return `<div class="code-preview ${large?'code-preview-large':''}"><div class="code-tab"><span class="file-dot orange"></span>auth.ts <span>TypeScript</span></div><pre aria-label="Example token refresh function"><code>${code.split('\n').map((line,i)=>`<span class="code-line"><span class="line-number" aria-hidden="true">${i+1}</span><span>${escape(line).replace(/\b(export|async|function|const|await|return|if|throw|new)\b/g,'<b>$1</b>')}</span></span>`).join('')}</code></pre></div>`;
 if(sample.id==='audio')return `<div class="audio-preview"><div class="audio-wave" aria-hidden="true">${Array.from({length:39},(_,i)=>`<i style="--bar:${14+Math.round(Math.abs(Math.sin(i*2.12))*48)}px;--delay:${i*-.06}s"></i>`).join('')}</div><strong>Class notes</strong><span class="audio-context">Matching segment · 0:30</span><audio controls preload="none" data-start="30" src="assets/class-notes.wav" aria-label="Play the fictional classroom excerpt"></audio><p>“The exam is on Friday.”</p></div>`;
 if(sample.id==='video')return `<video class="sample-video" controls playsinline preload="none" poster="assets/lake.webp" data-start="5" aria-label="Play the lake scene at five seconds"><source src="assets/lake.mp4#t=5" type="video/mp4"><track kind="captions" src="assets/lake.vtt" srclang="en" label="Scene description"></video>`;
 return `<img class="sample-image sample-image-${sample.id}" src="${sample.asset}" alt="${escape(sample.alt)}" width="${sample.id==='document'?1070:1440}" height="${sample.id==='document'?745:810}" ${large?'loading="lazy"':'fetchpriority="high"'}>`;
}

export function SearchDemo(){const sample=samples[0];return `<div class="search-demo" id="search-demo"><div class="demo-topline"><span><i class="status-dot"></i> A LOOK INSIDE TROVARA</span><span class="sample-label">Interactive sample</span></div><div class="search-window"><form class="search-field" id="demo-form" role="search" aria-label="Search the sample files"><span class="search-mark" aria-hidden="true"><svg viewBox="0 0 24 24"><defs><linearGradient id="search-gradient" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#d9a17a"/><stop offset="50%" stop-color="#79b9b0"/><stop offset="100%" stop-color="#b1a3d1"/></linearGradient></defs><circle cx="10" cy="10" r="6.4"/><path d="m15 15 5.3 5.3"/></svg><i class="search-spark">✦</i></span><label class="sr-only" for="demo-query">Search the fictional sample files</label><input id="demo-query" name="query" value="a red car" placeholder="Describe one of the sample files…" autocomplete="off" spellcheck="false"><button type="submit" class="search-submit" aria-label="Search samples">${icon('arrow')}</button></form><div class="demo-content"><aside class="demo-results"><div class="results-heading"><span id="demo-group">IMAGES</span><span>1 result</span></div><button class="result-row selected" id="selected-result" type="button" aria-label="Preview DSC_1001.png"><span class="result-thumb" id="demo-thumb"><img src="assets/red-car.webp" alt="" width="44" height="44"></span><span><strong id="demo-file">DSC_1001.png</strong><small id="demo-path">C:\\Demo\\Pictures</small></span>${icon('arrow')}</button><div class="match-note"><span class="match-note-label">${icon('search')} WHY IT MATCHED</span><p id="demo-reason">The image contains a red car. Its filename does not.</p></div></aside><div class="demo-preview"><div class="preview-asset" id="demo-asset">${sampleMedia(sample)}</div><div class="preview-caption"><div><strong id="demo-preview-name">DSC_1001.png</strong><span id="demo-match">${icon('check')} Matches the picture</span></div><button type="button" class="preview-button" id="open-preview">${icon('expand')}<span>Preview</span></button></div></div></div><div class="demo-footer"><span>Example files only · your files are not accessed</span><span class="demo-keyhint"><kbd>↵</kbd> Preview <kbd>←</kbd><kbd>→</kbd> Samples</span></div></div><div class="demo-samples" role="group" aria-label="Choose a sample search">${samples.map((s,i)=>`<button type="button" data-sample="${s.id}" aria-pressed="${i===0}" class="sample-chip ${i===0?'active':''}">${icon(s.icon)}${s.label}</button>`).join('')}</div><p class="demo-feedback" id="demo-feedback" role="status">Try a description above, or select another file type.</p></div>`;}

export function Hero(){return `<section class="hero container" aria-labelledby="hero-heading"><div class="hero-copy"><div class="eyebrow"><span class="tiny-dot"></span> LOCAL FILE SEARCH FOR WINDOWS <span class="beta-tag">BETA</span></div><h1 id="hero-heading">Describe it. <span>Find it.</span></h1><p class="hero-description">You remember what’s in the file.<br class="desktop-break"> Trovara helps you find it on your PC.</p><div class="hero-actions">${getButton()}<button class="button button-video" type="button" data-watch>${icon('play')}Watch the demo <span class="duration">75s</span></button></div><div class="hero-meta"><span>${icon('shield')}Files stay local</span><i></i><span>No account</span><i></i><span>Windows 10 / 11</span></div></div>${SearchDemo()}</section>`;}

export function Workflow(){return `<section class="section workflow" id="how-it-works" aria-labelledby="workflow-heading"><div class="container"><div class="section-heading"><div><span class="eyebrow">A SHORT SETUP. A FAMILIAR SHORTCUT.</span><h2 id="workflow-heading">Your folders.<br>Your way of finding things.</h2></div><p>Select what Trovara can read.<br>Then search with the details you remember.</p></div><div class="workflow-grid"><article class="step"><div class="step-art folder-art" aria-hidden="true"><div><span>${icon('folder')} Documents</span><span class="folder-check">${icon('check')}</span></div><div><span>${icon('image')} Pictures</span><span class="folder-check">${icon('check')}</span></div><div><span>${icon('audio')} Recordings</span><span class="folder-check">${icon('check')}</span></div></div><span class="step-number">01 / CHOOSE</span><h3>Start with your folders.</h3><p>Choose the places you want to search. Change them at any time in Settings.</p></article><article class="step"><div class="step-art index-art" aria-hidden="true"><div class="index-file">${icon('document')}<span>Reading your files<small>Building a local index</small></span><span class="index-dot"></span></div><div class="index-progress"><span></span></div><div class="index-caption">On this PC ${icon('shield')}</div></div><span class="step-number">02 / INDEX</span><h3>Let Trovara read them.</h3><p>Download the model once. Background indexing makes your file contents searchable.</p></article><article class="step"><div class="step-art shortcut-art" aria-hidden="true"><div><kbd>Ctrl</kbd><span>+</span><kbd>Shift</kbd><span>+</span><kbd>Space</kbd></div><span class="shortcut-caption">Search from any app</span></div><span class="step-number">03 / FIND</span><h3>Describe what you need.</h3><p>Open search with the shortcut. Inspect the matching page, image, moment, or code line.</p></article></div><p class="setup-note">${icon('document')} One-time model download: about 865 MB. First indexing takes time. New and changed files are read later.</p></div></section>`;}

export function FileTypes(){return `<section class="section file-types container" id="file-types" aria-labelledby="files-heading"><div class="section-heading"><div><span class="eyebrow">SEARCH BEYOND THE FILENAME</span><h2 id="files-heading">Different files.<br>One place to look.</h2></div><p>Find the part that matters.<br>Preview it before you open the file.</p></div><div class="file-explorer"><div class="file-type-tabs" role="tablist" aria-label="Supported file types" aria-orientation="vertical">${samples.map((s,i)=>`<button type="button" role="tab" id="tab-${s.id}" aria-controls="file-panel" aria-selected="${i===0}" tabindex="${i===0?'0':'-1'}" data-file-tab="${s.id}" class="file-tab ${i===0?'active':''}"><span class="type-icon ${s.color}">${icon(s.icon)}</span><span>${s.label}${s.id==='code'?'<small>Optional</small>':''}</span>${icon('arrow')}</button>`).join('')}</div><div class="file-panel" role="tabpanel" id="file-panel" aria-labelledby="tab-image" tabindex="0"><div class="feature-media" id="feature-media">${sampleMedia(samples[0],{large:true})}<span class="media-badge" id="feature-badge">Visual match</span></div><div class="feature-copy"><h3 id="feature-title">${samples[0].title}</h3><p id="feature-detail">${samples[0].detail}</p><div class="format-list" id="format-list">${samples[0].formats.map(f=>`<span>${f}</span>`).join('')}</div><p class="feature-note" id="feature-note">${samples[0].note}</p></div></div></div></section>`;}

export function Privacy(){return `<section class="section privacy-section" id="privacy" aria-labelledby="privacy-heading"><div class="container privacy-layout"><div class="privacy-copy"><span class="eyebrow">ON YOUR PC. UNDER YOUR CONTROL.</span><h2 id="privacy-heading">Your files stay<br>where they belong.</h2><p>Trovara runs its search model locally. Your files, queries, and indexes stay on your PC.</p><div class="privacy-points"><span>${icon('check')}No account or API key</span><span>${icon('check')}Offline search after setup</span><span>${icon('check')}You choose the indexed folders</span></div><details class="model-details"><summary>What does EmbeddingGemma 2 do? ${icon('plus')}</summary><p>Google DeepMind’s model turns text, images, and audio into numerical representations called embeddings. Trovara compares these representations to find content that matches your description.</p><p>Keyword search also matches exact words and file names. The model runs on your PC through llama.cpp. It does not train on your files or generate chat answers.</p><a href="https://ai.google.dev/gemma/docs/embeddinggemma/model_card_2" target="_blank" rel="noopener noreferrer">Read Google’s model card ${icon('external')}</a></details></div><div class="local-illustration" aria-label="Selected files and the search model stay on the same PC"><div class="local-files" aria-hidden="true">${[['document','blue'],['video','red'],['image','green'],['audio','lilac']].map(([g,c])=>`<span class="local-file ${c}">${icon(g)}</span>`).join('')}</div><div class="local-boundary"><span class="local-boundary-label">YOUR PC</span><div class="local-logo"><img src="assets/logo.png" width="118" height="118" alt=""><span>Trovara</span></div><div class="local-state">${icon('shield')} Local model + local index</div><div class="local-folder"><span>${icon('folder')} Selected folders</span>${icon('check')}</div></div><div class="local-footnote">${icon('wifi')}Search works offline after the model download.</div></div></div><div class="container privacy-network-note">Internet access is used for model downloads, update checks, and requested add-ons. You can disable update checks.</div></section>`;}

export function Comparison(){return `<section class="section comparison container" aria-labelledby="comparison-heading"><div class="section-heading"><div><span class="eyebrow">A DIFFERENT PART OF YOUR WORKFLOW</span><h2 id="comparison-heading">Find first.<br>Then take a closer look.</h2></div><p>Search tools find items.<br>Preview tools show the file you selected.</p></div><div class="comparison-table-wrap" tabindex="0" role="region" aria-label="Product comparison table"><table><thead><tr><th scope="col">Tool</th><th scope="col">Platform</th><th scope="col">Primary purpose</th></tr></thead><tbody><tr class="our-row"><th scope="row"><img src="assets/logo.png" alt="" width="30" height="30">Trovara</th><td>Windows</td><td>Find local file content by words and descriptions. Preview the matching page, moment, or code line.</td></tr><tr><th scope="row">Spotlight</th><td>macOS</td><td>Search apps, files, and system information. Preview items and perform supported actions.</td></tr><tr><th scope="row">Quick Look</th><td>macOS</td><td>Preview a selected file without opening its full application.</td></tr><tr><th scope="row">QuickLook</th><td>Windows</td><td>Preview selected files with Space. Extend format support with plugins.</td></tr></tbody></table></div><p class="comparison-sources">Product references: <a href="https://support.apple.com/guide/mac-help/search-with-spotlight-mchlp1008/mac" target="_blank" rel="noopener noreferrer">Spotlight</a><span>·</span><a href="https://support.apple.com/guide/mac-help/view-and-edit-files-with-quick-look-mh14119/mac" target="_blank" rel="noopener noreferrer">Quick Look</a><span>·</span><a href="https://github.com/QL-Win/QuickLook" target="_blank" rel="noopener noreferrer">QuickLook for Windows</a></p></section>`;}

export function FAQ(){return `<section class="section faq-section container" id="faq" aria-labelledby="faq-heading"><div class="faq-intro"><span class="eyebrow">A FEW PRACTICAL ANSWERS</span><h2 id="faq-heading">Before you<br>get started.</h2><p>More details are in the <a href="${config.repository}#readme" target="_blank" rel="noopener noreferrer">project README ${icon('external')}</a>.</p></div><div class="faq-list">${faqs.map(([q,a],i)=>`<details name="faq" class="faq-item"><summary>${escape(q)}${icon('plus')}</summary><div class="faq-answer"><p>${escape(a)}</p>${i===6?'<a href="https://ai.google.dev/gemma/docs/embeddinggemma/model_card_2" target="_blank" rel="noopener noreferrer">Model language support '+icon('external')+'</a>':''}</div></details>`).join('')}</div></section>`;}

export function Download(){return `<section class="section download-section container" id="download" aria-labelledby="download-heading"><div class="download-panel"><div class="download-copy"><img class="download-logo" src="assets/logo.png" alt="" width="72" height="72"><span class="eyebrow">TROVARA FOR WINDOWS</span><h2 id="download-heading">Keep your files.<br>Find what’s in them.</h2><p>Local content search, one shortcut away.</p><a id="release-button" class="button button-primary" href="${config.releases}" target="_blank" rel="noopener noreferrer">${icon('windows')}<span>View release status</span>${icon('external')}</a><p class="release-note" id="release-note" role="status">View the Windows installer and release notes on GitHub.</p></div><aside class="requirements"><h3>Before installing</h3><dl><div><dt>System</dt><dd>Windows 10 (22H2) / 11<br>64-bit</dd></div><div><dt>Memory</dt><dd>8 GB RAM minimum<br>16 GB recommended</dd></div><div><dt>Storage</dt><dd>About 2 GB free<br>More for indexes and previews</dd></div><div><dt>Model</dt><dd>865 MB, downloaded once<br>CPU or supported Vulkan GPU</dd></div></dl><span class="requirements-note">Beta software · Select the folders you want to index.</span></aside></div></section>`;}

export function Footer(){return `<footer class="site-footer"><div class="container footer-main"><div>${brand()}<p>Local file search for Windows.</p></div><div class="footer-links"><a href="${config.repository}" target="_blank" rel="noopener noreferrer">GitHub ${icon('external')}</a><a href="${config.releases}" target="_blank" rel="noopener noreferrer">Releases</a><a href="${config.repository}/blob/main/LICENSE" target="_blank" rel="noopener noreferrer">MIT license</a><a href="#privacy">Privacy</a><a href="credits.html">Credits</a></div></div><div class="container footer-bottom"><span>© ${new Date().getFullYear()} Subhankar Patra</span><span>Describe it. Find it.</span><a href="#">Back to top ↑</a></div></footer>`;}

export function Dialogs(){return `<dialog class="video-dialog" id="video-dialog" aria-labelledby="video-title"><div class="dialog-toolbar"><h2 id="video-title">Meet Trovara <span>75-second product demo</span></h2><button type="button" class="icon-button" data-close-dialog aria-label="Close video">${icon('close')}</button></div><video id="product-video" controls playsinline preload="none" poster="assets/demo-poster.jpg"><source src="assets/demo.mp4" type="video/mp4"><track default kind="captions" src="assets/demo.vtt" srclang="en" label="English"></video><p class="dialog-note">Demo files are fictional. Music: Airport Lounge — Kevin MacLeod, CC BY 4.0. <a href="credits.html">Media credits</a></p></dialog><dialog class="preview-dialog" id="preview-dialog" aria-labelledby="preview-title"><div class="dialog-toolbar"><h2 id="preview-title">Sample preview</h2><button class="icon-button" type="button" data-close-dialog aria-label="Close preview">${icon('close')}</button></div><div id="modal-preview"></div><p class="dialog-note" id="preview-description"></p></dialog><div class="toast" id="toast" role="status" hidden></div>`;}
